func TestHashReset(t *testing.T) {
	// hash a single element using Merkle-Damgard and a nonzero IV, twice
	var iv, b [fr.Bytes]byte
	iv[0] = 1
	_, err := rand.Read(b[:])
	require.NoError(t, err)
	b[0] &= msbMask
	p := Permutation{GetDefaultParameters()}
	h := hash.NewMerkleDamgardHasher(&p, iv[:])
	_, err = h.Write(b[:])
	require.NoError(t, err)
	res := h.Sum(nil)

	h.Reset()
	_, err = h.Write(b[:])
	require.NoError(t, err)

	require.Equal(t, res, h.Sum(nil))
}

// denseMatrixMul returns m·x.
func denseMatrixMul(m [][]fr.Element, x []fr.Element) []fr.Element {
	res := make([]fr.Element, len(m))
	for i := range m {
		var tmp fr.Element
		for j := range m[i] {
			tmp.Mul(&m[i][j], &x[j])
			res[i].Add(&res[i], &tmp)
		}
	}
	return res
}

